export const condenserScenarioVersion = 3;

/** Creates identical, isolated source preparations for every strategy. */
export async function condenserScenarios(): Promise<{development: PreparedBenchmarkCase[]; holdout: PreparedBenchmarkCase[]}> {
    const cases = scenarios.map(buildCondenserScenario);
    return {
        development: cases.filter((item) => item.definition.id !== "generic-analysis-05" && item.definition.id !== "generic-drafting-06"),
        holdout: cases.filter((item) => item.definition.id === "generic-analysis-05" || item.definition.id === "generic-drafting-06")
    };
}
